#include "v32_rate.h"
static const enum v32_carrier_state pair_state[4]={V32_STATE_A,V32_STATE_B,V32_STATE_D,V32_STATE_C};
static unsigned state_pair(enum v32_carrier_state s){static const unsigned p[4]={0,1,3,2};return p[s&3];}
void v32_rate_tx_init(struct v32_rate_tx*t,enum v32_std_role role,uint16_t word,enum v32_carrier_state previous){v32_std_scrambler_init(&t->scr,role);t->word=word;t->bit=0;t->previous=state_pair(previous);}
enum v32_carrier_state v32_rate_tx_next(struct v32_rate_tx*t){int a=(t->word>>(t->bit++&15))&1,b=(t->word>>(t->bit++&15))&1;a=v32_std_scramble(&t->scr,a);b=v32_std_scramble(&t->scr,b);t->previous=v32_std_diff_encode((unsigned)((a<<1)|b),t->previous);return pair_state[t->previous];}
void v32_rate_rx_init(struct v32_rate_rx*r,enum v32_std_role role,enum v32_carrier_state previous){v32_std_scrambler_init(&r->descr,role);r->word=r->last=0;r->bits=r->repeats=0;r->previous=state_pair(previous);r->detected=0;}
int v32_rate_rx_put(struct v32_rate_rx*r,enum v32_carrier_state state,uint16_t*out){unsigned current=state_pair(state),q=0;for(;q<4;q++)if(v32_std_diff_encode(q,r->previous)==current)break;r->previous=current;if(q==4)return 0;int a=v32_std_descramble(&r->descr,(q>>1)&1),b=v32_std_descramble(&r->descr,q&1);r->word|=(uint16_t)a<<r->bits++;r->word|=(uint16_t)b<<r->bits++;if(r->bits<16)return 0;unsigned rates;int tr,bis,valid=v32bis_rate_decode(r->word,&rates,&tr,&bis)==0;if(valid&&r->word==r->last)r->repeats++;else r->repeats=valid?1:0;r->last=r->word;r->word=0;r->bits=0;if(r->repeats>=2){r->detected=1;if(out)*out=r->last;return 1;}return 0;}
